"""Layout switch: masonry by default, Grid makes every tile the same size. Run: python tests/layout_test.py"""
import os
from playwright.sync_api import sync_playwright
PAGE = 'file://' + os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'site', 'index.html'))
bad = []
def check(n, ok):
    print(('PASS ' if ok else 'FAIL ') + n)
    if not ok: bad.append(n)
H = 'id,permalink,starred,updated,deleted\r\n'
rows = ''.join('p%05d,/r/pics/comments/p%05d/t/,0,1000,0\r\n' % (i, i) for i in range(12))
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={'width': 1100, 'height': 800}); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.route('**/*', lambda r: r.continue_() if r.request.url.startswith('file:') else r.abort())
    pg.goto(PAGE); pg.wait_for_timeout(800); ev = pg.evaluate
    ev("""async(t)=>{ await persistRec({id:'x',name:'x.csv',text:t,handle:null,updated:Date.now()}); await activate(await idbReq('csv','readonly',s=>s.get('x'))); for(const k in META) delete META[k]; startCsvMode(); }""", H + rows)
    pg.wait_for_timeout(600)
    ev("""()=>{ POSTS.forEach((p,i)=>{ META[p.id] = {t:'T'+i,o:0,th:'https://i.redd.it/a.jpg',m:'image',u:'',n:0,s:0,a:'',c:0,w:i%2?1600:400,h:i%2?400:900}; }); state.hideBroken=false; refresh(); }""")
    pg.wait_for_timeout(400)
    ev('relayoutAll()')
    rows_ = lambda: ev("[...new Set([...document.querySelectorAll('#grid .card')].map(c=>c.style.gridRow))]")
    check('masonry is the default', ev("LAYOUT")=='masonry' and ev("document.querySelector('#layoutseg [data-l=masonry]').getAttribute('aria-pressed')")=='true')
    check('cards present', ev("document.querySelectorAll('#grid .card').length") > 5)
    check('masonry has mixed heights', len(rows_()) > 1)
    ev("document.querySelector('#layoutseg [data-l=grid]').click()")
    check('grid: all tiles same size', len(rows_()) == 1 and ev("[...document.querySelectorAll('#grid .card')].every(c=>!c.style.gridColumn)"))
    ev("document.querySelector('#layoutseg [data-l=list]').click()")
    check('list: every row the same short height', ev("[...new Set([...document.querySelectorAll('#grid .card')].map(c=>c.style.gridRow))]") == ['span 9'])
    check('list: card info defaults to always visible', ev("document.getElementById('infomode').value")=='show' and not ev("document.body.classList.contains('info-off')"))
    check('list: rows are wide and short', ev("(()=>{ const r=document.querySelector('#grid .card').getBoundingClientRect(); return r.height < 100 && r.width > 2*r.height; })()"))
    check('list: info overlay fills the row', ev("(()=>{ const c=document.querySelector('#grid .card'), i=c.querySelector('.info'); if(!i) return false; const a=c.getBoundingClientRect(), b=i.getBoundingClientRect(); return getComputedStyle(i).display!=='none' && Math.abs(a.height-b.height)<4; })()"))
    check('list: small square thumbnail on the left, text beside it', ev("(()=>{ const c=document.querySelector('#grid .card'), t=c.querySelector('.thumb').getBoundingClientRect(), i=c.querySelector('.title').getBoundingClientRect(), cr=c.getBoundingClientRect(); return Math.abs(t.width-t.height)<1 && t.width<=72 && t.left-cr.left<16 && i.left>=t.right; })()"))
    check('list: solid row background (no blurred picture behind the text)', ev("(()=>{ const c=document.querySelector('#grid .card'); const bg=getComputedStyle(c).backgroundColor; return bg!=='rgba(0, 0, 0, 0)' && getComputedStyle(c.querySelector('.info')).backgroundImage==='none'; })()"))
    lefts = lambda: ev("new Set([...document.querySelectorAll('#grid .card')].map(c=>Math.round(c.getBoundingClientRect().left))).size")
    check('list: Columns control is visible, defaults to 1 and caps row width', ev("getComputedStyle(document.getElementById('colsrow')).display")!='none' and ev("document.querySelector('#colsseg [aria-pressed=true]').dataset.c")=='1' and lefts()==1 and ev("document.querySelector('#grid .card').getBoundingClientRect().width")<=690)
    ev("document.querySelector('#colsseg [data-c=\"2\"]').click()"); pg.wait_for_timeout(200)
    check('list: 2 columns', lefts()==2)
    ev("document.querySelector('#colsseg [data-c=auto]').click()"); pg.wait_for_timeout(200)
    check('list: Auto fills as many as fit', lefts()>=2 and ev("localStorage.getItem('saved-posts-listcols')")=='auto')
    ev("document.querySelector('#colsseg [data-c=\"1\"]').click()")
    pg.hover('#grid .card .thumb'); pg.wait_for_timeout(500)
    check('list: no playback or media controls on hover', ev("!document.querySelector('#grid .card video.clip, #grid .card iframe.clip, #grid .card .ctl') || getComputedStyle(document.querySelector('#grid .card .ctl')||document.body).display==='none'"))
    ev("(()=>{ const s=document.getElementById('infomode'); s.value='hover'; s.dispatchEvent(new Event('change')); })()")
    ev("document.querySelector('#layoutseg [data-l=masonry]').click()")
    check('Columns control is hidden outside List', ev("getComputedStyle(document.getElementById('colsrow')).display")=='none')
    check('leaving List restores the other layouts\' own card-info setting', ev("document.getElementById('infomode').value")=='hover')
    ev("document.querySelector('#layoutseg [data-l=list]').click()")
    check('List remembers its own card-info choice', ev("document.getElementById('infomode').value")=='hover')
    ev("document.querySelector('#layoutseg [data-l=masonry]').click()")
    ev("document.querySelector('#layoutseg [data-l=masonry]').click()"); pg.wait_for_timeout(200)
    def gap():
        return ev("""(()=>{ const c=[...document.querySelectorAll('#grid .card')].find(x=>x.querySelector('.fs')&&x.querySelector('.save')); const st=c.querySelector('.star').getBoundingClientRect(), a=c.querySelector('.fs').getBoundingClientRect(); const fs=c.querySelector('.fs'); const g1=Math.round(st.left-a.right); fs.remove(); const sv=c.querySelector('.save').getBoundingClientRect(); return [g1, Math.round(st.left-sv.right)]; })()""")
    g = gap()
    check('without a full-screen button the save button closes the gap', abs(g[0]-g[1]) <= 1)
    check('hint names Masonry as best for media', 'media' in ev("document.getElementById('layouthint').textContent"))
    ev("document.querySelector('#layoutseg [data-l=list]').click()")
    check('hint names List as best for text posts', 'text posts' in ev("document.getElementById('layouthint').textContent"))
    pg.set_viewport_size({'width': 390, 'height': 700}); pg.wait_for_timeout(400)
    ev("document.querySelector('#layoutseg [data-l=list]').click()"); pg.wait_for_timeout(300)
    vis = lambda sel: ev("(()=>{ const e=document.querySelector('#grid .card %s'); return !!e && getComputedStyle(e).display!=='none'; })()" % sel)
    check('phone list: only the fold button shows, card buttons are tucked away', vis('.morebtn') and not vis('.star') and not vis('.save'))
    check('phone list: title column keeps its width', ev("(()=>{ const c=document.querySelector('#grid .card'), i=c.querySelector('.info'); return c.getBoundingClientRect().width - parseFloat(getComputedStyle(i).paddingRight) - parseFloat(getComputedStyle(i).paddingLeft) > 200; })()"))
    ev("document.querySelector('#grid .card .morebtn').click()"); pg.wait_for_timeout(300)
    check('phone list: fold button opens the buttons', vis('.star') and vis('.save') and ev("document.querySelector('#grid .card').classList.contains('btns-open')"))
    check('phone list: meta stays on one line so the title is never cut', ev("(()=>{ const c=document.querySelector('#grid .card'), i=c.querySelector('.info'); const a=c.getBoundingClientRect(), b=i.getBoundingClientRect(); return i.scrollHeight <= i.clientHeight+1 && b.top>=a.top-1 && b.bottom<=a.bottom+1; })()"))
    ev("document.querySelector('#grid .card .morebtn').click()"); pg.wait_for_timeout(200)
    check('fold button closes them again', not vis('.star'))
    pg.set_viewport_size({'width': 1100, 'height': 800}); pg.wait_for_timeout(300)
    check('wide list: fold button hidden, buttons visible', not vis('.morebtn') and vis('.star'))
    ev("document.querySelector('#layoutseg [data-l=grid]').click()")
    ev("document.querySelector('#layoutseg [data-l=grid]').click()")
    pg.reload(); pg.wait_for_timeout(800)
    check('grid choice is remembered', ev("LAYOUT")=='grid')
    ev("document.querySelector('#layoutseg [data-l=masonry]').click()")
    check('back to masonry', ev("LAYOUT")=='masonry')
    check('no page errors', not errs)
    b.close()
print('FAILED: ' + ', '.join(bad) if bad else 'ALL PASS')
